type Order = { id: number; accountId: number; customerId: number; version: number; status: "open" | "cancelled"; amount: number; date: string };
type Ports = {
  refund(orderId: number, amount: number): Promise<void>;
  insert(order: Order, ledgerId?: number): Promise<void>;
  openLedger(accountId: number, customerId: number): Promise<number>;
  assertOpenPeriod(accountId: number, date: string): Promise<void>;
};
export async function cancel(order: Order, ports: Ports) {
  await ports.refund(order.id, order.amount);
  order.status = "cancelled";
  order.version += 1;
}
export function revise(order: Order, amount: number) {
  order.amount = amount;
  order.version += 1;
}
export async function create(order: Order, ports: Ports) {
  await ports.insert(order);
}
export async function pay(order: Order, ports: Ports) {
  const ledgerId = await ports.openLedger(order.accountId, order.customerId);
  await ports.assertOpenPeriod(order.accountId, order.date);
  if (order.amount <= 0) throw new Error("invalid amount");
  await ports.insert(order, ledgerId);
}
export function allocate(amount: number, ownerIds: number[]) {
  return ownerIds.map(ownerId => ({ ownerId, amount }));
}
export function address(candidates: string[]) {
  return candidates[0];
}
